import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate, interpolateColors } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadSpaceGrotesk = makeLoadFont('SpaceGrotesk');

const { fontFamily: spaceGrotesk } = loadSpaceGrotesk();



export type AuditAnimationProps = Record<string, any>;

const WarningIcon: React.FC<{ size: number }> = ({ size }) => (
  <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
    <path d="M10.29 3.86L1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0z" />
    <line x1="12" y1="9" x2="12" y2="13" />
    <line x1="12" y1="17" x2="12.01" y2="17" />
  </svg>
);

const AuditAnimation: React.FC<AuditAnimationProps> = ({
  backgroundColor = "#080808",
  transparentBackground = false,
  durationInSeconds = 8,
  primaryPink = "#FF1493",
  secondaryDark = "#121212",
  textColor = "#F5F5F5",
  auditHeadline = "Auditing Ad Account",
  issuesHeadline = "Anomalies Detected",
  metrics = [
    { label: "DAILY SPEND", value: "$4,250", isIssue: false },
    { label: "COST PER ACQ", value: "$125.50", isIssue: true },
    { label: "CLICK RATE", value: "0.85%", isIssue: true },
    { label: "IMPRESSIONS", value: "45.2K", isIssue: false },
  ],
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Layout calculations - Updated for Vertical Stack
  const dashboardTop = height * 0.28;
  const dashboardWidth = width * 0.9;
  const dashboardLeft = (width - dashboardWidth) / 2;
  
  // Responsive sizing - Scaled up for full frame
  const titleSize = width * 0.075;
  const subtitleSize = width * 0.035;
  const metricLabelSize = width * 0.035;
  const metricValueSize = width * 0.08;
  const cardPadding = width * 0.05;
  const cardRadius = width * 0.03;
  const gapSize = height * 0.02;

  // Drone / Scanner Logic - Updated to scan vertically
  const scanStartFrame = 50;
  const scanEndFrame = 150;
  const droneX = width * 0.5;
  const droneY = interpolate(frame, [scanStartFrame, scanEndFrame], [height * 0.18, height * 0.95], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });
  const droneOpacity = interpolate(frame, [scanStartFrame - 10, scanStartFrame, scanEndFrame, scanEndFrame + 10], [0, 1, 1, 0], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });
  const rotorAngle = (frame * 35) % 360;
  const droneHover = Math.sin(frame * 0.15) * (height * 0.01);

  // Text Logic
  const showAuditPhase = frame < 140;
  const statusText = "SYSTEM STATUS:";
  const statusChars = Math.floor(interpolate(frame, [10, 30], [0, statusText.length], { extrapolateRight: 'clamp' }));
  
  const auditTextFadeOut = interpolate(frame, [130, 140], [1, 0], { extrapolateRight: 'clamp' });
  const auditTextY = interpolate(spring({ fps, frame: frame - 20, config: { damping: 15 } }), [0, 1], [30, 0]);
  
  const issuesTextFadeIn = interpolate(frame, [140, 150], [0, 1], { extrapolateLeft: 'clamp' });
  const issuesTextY = interpolate(spring({ fps, frame: frame - 140, config: { damping: 15 } }), [0, 1], [30, 0]);

  // Background Grid Variables
  const gridSize = width * 0.05;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: spaceGrotesk }}>
      
      {/* Background Grid Pattern & Vignette */}
      <svg width="100%" height="100%" style={{ position: 'absolute', pointerEvents: 'none', zIndex: 0 }}>
        <defs>
          <pattern id="gridPattern" width={gridSize} height={gridSize} patternUnits="userSpaceOnUse">
            <path d={`M ${gridSize} 0 L 0 0 0 ${gridSize}`} fill="none" stroke={textColor} strokeWidth="1" opacity="0.05"/>
          </pattern>
          <radialGradient id="vignette" cx="50%" cy="50%" r="70%">
             <stop offset="30%" stopColor={backgroundColor} stopOpacity="0" />
             <stop offset="100%" stopColor={backgroundColor} stopOpacity="1" />
          </radialGradient>
        </defs>
        <rect width="100%" height="100%" fill="url(#gridPattern)" />
        <rect width="100%" height="100%" fill="url(#vignette)" />
      </svg>

      {/* Top Text Panel */}
      <div style={{
        position: 'absolute',
        top: height * 0.08,
        width: '100%',
        display: 'flex',
        flexDirection: 'column',
        alignItems: 'center',
        zIndex: 10,
      }}>
        <div style={{ color: textColor, opacity: 0.6, fontSize: subtitleSize, letterSpacing: 4, marginBottom: height * 0.02, fontFamily: 'monospace', textAlign: 'center' }}>
          {statusText.substring(0, statusChars)}
          {frame % 15 < 7 && frame > 30 && showAuditPhase ? "_" : ""}
        </div>
        
        <div style={{ position: 'relative', height: titleSize * 3, width: '90%', display: 'flex', justifyContent: 'center' }}>
          {/* Audit Headline */}
          <div style={{
             position: 'absolute',
             opacity: auditTextFadeOut,
             transform: `translateY(${auditTextY}px)`,
             color: textColor,
             fontSize: titleSize,
             fontWeight: 800,
             lineHeight: 1.1,
             textTransform: 'uppercase',
             textAlign: 'center',
             display: 'flex',
             flexDirection: 'column',
             alignItems: 'center'
          }}>
             {auditHeadline}
             
             {/* Pulsing Dots */}
             <div style={{ display: 'flex', gap: 12, marginTop: height * 0.02 }}>
                {[0, 1, 2].map(i => {
                   const dotOp = (Math.sin((frame - i * 10) * 0.2) + 1) / 2;
                   return (
                     <div key={i} style={{ 
                       width: width * 0.02, 
                       height: width * 0.02, 
                       borderRadius: '50%', 
                       backgroundColor: primaryPink, 
                       opacity: showAuditPhase ? dotOp : 0 
                     }} />
                   );
                })}
             </div>
          </div>

          {/* Issues Headline */}
          <div style={{
             position: 'absolute',
             opacity: issuesTextFadeIn,
             transform: `translateY(${issuesTextY}px)`,
             color: primaryPink,
             fontSize: titleSize,
             fontWeight: 800,
             lineHeight: 1.1,
             textTransform: 'uppercase',
             textShadow: `0 0 20px ${primaryPink}44`,
             textAlign: 'center'
          }}>
             {issuesHeadline}
          </div>
        </div>
      </div>

      {/* Stacked Dashboard Grid */}
      <div style={{
         position: 'absolute',
         left: dashboardLeft,
         top: dashboardTop,
         width: dashboardWidth,
         display: 'flex',
         flexDirection: 'column',
         gap: `${gapSize}px`,
         zIndex: 5,
      }}>
         {metrics.map((metric, index) => {
            const maxIndex = Math.max(metrics.length - 1, 1);
            // Drone hits elements progressively as it scans down
            const hitFrame = Math.floor(interpolate(index, [0, maxIndex], [70, 130]));
            const isHit = frame >= hitFrame;
            const showIssue = metric.isIssue && isHit;

            const entry = spring({ fps, frame: frame - 20 - (index * 5), config: { damping: 14 } });
            const alert = spring({ fps, frame: showIssue ? frame - hitFrame : 0, config: { stiffness: 200, damping: 10 } });
            
            const flashVal = showIssue ? interpolate(frame - hitFrame, [0, 15, 30], [0, 1, 0], { extrapolateRight: 'clamp' }) : 0;
            const scale = interpolate(entry, [0, 1], [0.95, 1]) + (alert * 0.02);
            const opacity = interpolate(entry, [0, 1], [0, 1]);

            const cardBgColor = showIssue
               ? interpolateColors(alert, [0, 1], [secondaryDark, `${primaryPink}22`])
               : secondaryDark;
            const cardBorderColor = showIssue
               ? interpolateColors(alert, [0, 1], [`${textColor}22`, primaryPink])
               : `${textColor}11`;
            const shadowStyle = flashVal > 0 ? `0 0 ${flashVal * (width * 0.03)}px ${primaryPink}88` : 'none';

            return (
               <div key={index} style={{
                  transform: `scale(${scale})`,
                  opacity,
                  backgroundColor: cardBgColor,
                  border: `2px solid`,
                  borderColor: cardBorderColor,
                  borderRadius: cardRadius,
                  padding: cardPadding,
                  position: 'relative',
                  display: 'flex',
                  flexDirection: 'row',
                  justifyContent: 'space-between',
                  alignItems: 'center',
                  boxShadow: shadowStyle,
                  boxSizing: 'border-box',
                  width: '100%'
               }}>
                  <div style={{ color: textColor, opacity: 0.6, fontSize: metricLabelSize, letterSpacing: 1 }}>
                    {metric.label}
                  </div>
                  <div style={{ display: 'flex', alignItems: 'center', gap: width * 0.03 }}>
                    <div style={{ color: showIssue ? primaryPink : textColor, fontSize: metricValueSize, fontWeight: 700 }}>
                      {metric.value}
                    </div>
                    {showIssue && (
                       <div style={{
                          transform: `scale(${alert})`,
                          color: primaryPink,
                          display: 'flex'
                       }}>
                          <WarningIcon size={width * 0.06} />
                       </div>
                    )}
                  </div>
               </div>
            );
         })}
      </div>

      {/* The Motion Figure (Vertical Drone / Scanner) */}
      <div style={{
         position: 'absolute',
         left: droneX,
         top: droneY + droneHover,
         opacity: droneOpacity,
         zIndex: 20,
         transform: 'translate(-50%, -50%)',
         pointerEvents: 'none',
         width: width,
         display: 'flex',
         justifyContent: 'center'
      }}>
        <svg width={width} height={height * 0.5} style={{ overflow: 'visible' }}>
          <defs>
             <linearGradient id="beamGrad" x1="0" y1="0" x2="0" y2="1">
                <stop offset="0%" stopColor={primaryPink} stopOpacity="0.4" />
                <stop offset="10%" stopColor={primaryPink} stopOpacity="0.1" />
                <stop offset="100%" stopColor={primaryPink} stopOpacity="0.0" />
             </linearGradient>
             <filter id="glow">
                <feGaussianBlur stdDeviation="6" result="coloredBlur"/>
                <feMerge>
                   <feMergeNode in="coloredBlur"/>
                   <feMergeNode in="SourceGraphic"/>
                </feMerge>
             </filter>
          </defs>
          <g transform={`translate(${width * 0.5}, 0)`}>
             {/* Beam spanning wide across the cards */}
             <polygon 
               points={`-15,10 15,10 ${width * 0.45},${height * 0.3} -${width * 0.45},${height * 0.3}`} 
               fill="url(#beamGrad)" 
             />
             
             {/* Drone Body */}
             <rect 
               x={-width * 0.08} y={-height * 0.015} 
               width={width * 0.16} height={height * 0.03} 
               rx={height * 0.015} 
               fill={secondaryDark} 
               stroke={primaryPink} 
               strokeWidth="4" 
               filter="url(#glow)" 
             />
             
             {/* Lens / Eye */}
             <circle cx="0" cy="0" r={width * 0.015} fill={primaryPink} />
             <circle cx="0" cy="0" r={width * 0.025} fill="none" stroke={primaryPink} strokeWidth="2" opacity="0.5" />
             
             {/* Left Rotor */}
             <g transform={`translate(-${width * 0.06}, -${height * 0.02})`}>
                <line x1={-width * 0.03} y1="0" x2={width * 0.03} y2="0" stroke={primaryPink} strokeWidth="3" transform={`rotate(${rotorAngle})`} opacity="0.8" />
                <circle cx="0" cy="0" r="3" fill={primaryPink} />
             </g>

             {/* Right Rotor */}
             <g transform={`translate(${width * 0.06}, -${height * 0.02})`}>
                <line x1={-width * 0.03} y1="0" x2={width * 0.03} y2="0" stroke={primaryPink} strokeWidth="3" transform={`rotate(${rotorAngle})`} opacity="0.8" />
                <circle cx="0" cy="0" r="3" fill={primaryPink} />
             </g>
          </g>
        </svg>
      </div>

    </AbsoluteFill>
  );
};

export default AuditAnimation;